PREFIX brick: <http://brick.schema.org/> 
SELECT ?zone ?zoneTs ?hsp ?hspTs ?csp ?cspTs ?tempTs
WHERE {
  ?zone rdf:type brick:Zone ; rdfs:label "Perimeter_mid_ZN_1" .
  OPTIONAL { ?zone brick:hasHeatingSetpoint ?hsp . ?hsp ref:hasTimeseriesId ?hspTs . }
  OPTIONAL { ?zone brick:hasCoolingSetpoint ?csp . ?csp ref:hasTimeseriesId ?cspTs . }
  OPTIONAL { ?zone brick:hasMeasurement ?temp . ?temp ref:hasTimeseriesId ?tempTs . }
}

PREFIX brick: <http://brick.schema.org/> 
SELECT ?s ?class
WHERE {
  ?s ref:hasTimeseriesId "Perimeter_mid_ZN_1" .
  OPTIONAL { ?s rdf:type ?class . }
}

PREFIX brick: <http://brick.schema.org/> 
SELECT ?zone ?pred ?o ?oLabel ?oTs
WHERE {
  ?zone rdfs:label "Perimeter_mid_ZN_1" ; ?pred ?o .
  FILTER(?pred != rdf:type)
  OPTIONAL { ?o rdfs:label ?oLabel . }
  OPTIONAL { ?o ref:hasTimeseriesId ?oTs . }
}

